const isFollowUpContract = (precedingSteps: StepInput[]): boolean =>
  precedingSteps.some(isQuoteStep);

const runStep = (
  step: StepInput,
  customer: Customer,
  precedingSteps: StepInput[],
): QuoteResult => {
  if (isQuoteStep(step)) {
    return quoteStep(step, customer, isFollowUpContract(precedingSteps));
  }
  // Claim steps land here once they exist; until then an unrecognised op is a
  // scenario the spec has no example for.
  throw new Error(`Unsupported step op: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step, index) =>
    runStep(step, scenario.customer, scenario.steps.slice(0, index)),
  ),
});
